#define ITERATIONS 96
#define LIGHT_COLOR vec3(1.0, 0.9, 0.7)
#define AMBIENT 0.15
#define BACKGROUND_COLOR vec3(0.2, 0.4, 0.8) // 深蓝色背景

// 修复的摄像机矩阵
mat3 lookAt(vec3 eye, vec3 target, vec3 up) {
    vec3 z = normalize(target - eye); // 修正方向
    vec3 x = normalize(cross(z, normalize(up)));
    vec3 y = cross(x, z);
    return mat3(x, y, z);
}

// 改进的哈希函数
float hash(float n) {
    return fract(sin(n)*43758.5453);
}

// 修复的三维噪声（增加梯度计算）
float noise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f*f*(3.0-2.0*f);

    float n = i.x + i.y*157.0 + i.z*113.0;
    return mix(
        mix(mix(hash(n+0.0), hash(n+1.0),f.x),
            mix(hash(n+157.0), hash(n+158.0),f.x),f.y),
        mix(mix(hash(n+113.0), hash(n+114.0),f.x),
            mix(hash(n+270.0), hash(n+271.0),f.x),f.y),
        f.z
    ) * 2.0 - 1.0; // 输出范围修正为[-1,1]
}

// 调整后的FBM
float fbm(vec3 p) {
    float f = 0.0;
    f += 0.5000 * abs(noise(p)); p *= 2.02;
    f += 0.2500 * abs(noise(p)); p *= 2.03;
    f += 0.1250 * abs(noise(p)); p *= 2.01;
    f += 0.0625 * abs(noise(p));
    return f/0.9375;
}

// 增强的密度场
float density(vec3 pos) {
    // 核心形状
    float base = exp(-length(pos)*0.8); // 指数衰减更自然

    // 湍流噪声
    vec3 q = pos * 0.8 + vec3(0, iTime*0.5, 0);
    float turbulence = fbm(q*3.0) * 1.8;

    // 动态涡旋
    float angle = iTime * 0.7;
    vec3 vortex = pos;
    vortex.xz *= mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    float vortexFactor = fbm(vortex*1.5) * 0.8;

    return clamp(base * (1.0 + turbulence + vortexFactor), 0.0, 1.0);
}


// 相位函数（双散射项）
float phase(float cosTheta) {
    const float g1 = 0.8;
    const float g2 = -0.4;
    const float w = 0.7;
    return mix(
        (1.0 - g1*g1)/(4.0*3.1416*pow(1.0 + g1*g1 - 2.0*g1*cosTheta, 1.5)),
        (1.0 - g2*g2)/(4.0*3.1416*pow(1.0 + g2*g2 - 2.0*g2*cosTheta, 1.5)),
        w
    );
}

// 增强的光线步进
vec4 render(vec3 ro, vec3 rd) {
    float t = 0.0, maxT = 12.0;
    vec3 acc = vec3(0);
    float trans = 1.0;
    float step = 0.1;

    for(int i=0; i<ITERATIONS; ++i) {
        if(trans < 0.01 || t > maxT) break;

        vec3 p = ro + rd*t;
        float dens = density(p);

        if(dens > 0.01) {
            vec3 lightDir = normalize(vec3(2,3,1));
            float shadow = exp(-density(p + lightDir*0.5)*4.0);

            // 增强光照对比度
            float lightIntensity = shadow * (1.0 + 2.0*dens);
            vec3 scatter = (phase(dot(rd, lightDir))*LIGHT_COLOR*lightIntensity + AMBIENT)
                          * dens * exp(-t*0.15);

            acc += scatter * trans * step;
            trans *= exp(-dens*step*6.0);
        }

        step = mix(0.08, 0.15, smoothstep(0.0,1.0,dens));
        t += step;
    }

    // 背景混合
    return vec4(mix(BACKGROUND_COLOR, acc, 1.0 - trans), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord*2.0 - iResolution.xy)/iResolution.y;

    // 摄像机设置
    float time = iTime * 0.5;
    vec3 ro = vec3(4.0*sin(time), 2.0*cos(time*0.5), 4.0*cos(time));
    vec3 ta = vec3(0, 0, 0);
    mat3 cam = lookAt(ro, ta, vec3(0,1,0));
    vec3 rd = cam * normalize(vec3(uv, 1.2));

    vec4 col = render(ro, rd);

    // 增强颜色处理
    col.rgb = pow(col.rgb * 1.5, vec3(1.8)); // 提高对比度
    col.rgb = col.rgb/(1.0 + col.rgb); // Reinhard tone mapping
    col.rgb = pow(col.rgb, vec3(1.0/2.2)); // Gamma校正

    fragColor = vec4(col.rgb, 1.0);
}
